"""
report_configuration.py — Module 18: Medical Report Generation Engine
Medical AI Platform — Configuration dataclass for medical report generation.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import List

from medical_ai_engine.reporting.reporting_exceptions import ReportingConfigurationError

DEFAULT_DISCLAIMER = (
    "DISCLAIMER: This report is generated by an automated Medical AI Diagnostic & "
    "Anomaly Detection system. It is intended solely for clinical decision support and "
    "preliminary triage. This AI output does NOT constitute a final medical diagnosis or "
    "legal diagnostic opinion. All findings, risk assessments, and recommendations MUST "
    "be reviewed, validated, and signed off by a licensed healthcare professional before "
    "clinical action is taken."
)


@dataclass
class ReportConfiguration:
    """
    Configuration options for report generation and export.

    Attributes
    ----------
    institution_name : str
        Name of the healthcare institution or platform.
    include_disclaimer : bool
        Whether to attach mandatory clinical AI disclaimer.
    disclaimer_text : str
        Text of the clinical AI disclaimer.
    export_formats : List[str]
        Supported export file formats (e.g. ['json', 'markdown', 'pdf']).
    default_output_directory : str
        Default target directory for exported reports.
    include_heatmap_references : bool
        Whether to include explainability heatmap artifact references.
    include_anomaly_details : bool
        Whether to include OOD / Unknown Disease detection details.
    """

    institution_name: str = "Medical AI Diagnostic & Anomaly Detection Platform"
    include_disclaimer: bool = True
    disclaimer_text: str = DEFAULT_DISCLAIMER
    export_formats: List[str] = field(default_factory=lambda: ["json", "markdown", "pdf"])
    default_output_directory: str = "docs"
    include_heatmap_references: bool = True
    include_anomaly_details: bool = True

    def __post_init__(self) -> None:
        if not self.institution_name.strip():
            raise ReportingConfigurationError("institution_name cannot be empty.")
        if not self.export_formats:
            raise ReportingConfigurationError("export_formats list cannot be empty.")
        valid_formats = {"json", "markdown", "pdf"}
        for fmt in self.export_formats:
            if fmt.lower() not in valid_formats:
                raise ReportingConfigurationError(f"Unsupported export format: {fmt!r}")

    @classmethod
    def default(cls) -> ReportConfiguration:
        """Production default configuration."""
        return cls()

    @classmethod
    def fast_test(cls) -> ReportConfiguration:
        """Fast configuration for unit testing."""
        return cls(
            export_formats=["json", "markdown", "pdf"],
            default_output_directory="docs",
        )


__all__ = ["ReportConfiguration", "DEFAULT_DISCLAIMER"]
